"""Generated bytes only; OwnerView double is NOT a production recovery adapter."""
import json
import tarfile
from contextlib import contextmanager
from types import SimpleNamespace

import pytest
from hermes_cpa.config_store import ConfigStore
from hermes_cpa.installer import CpaInstaller
from hermes_cpa.runtime_manifest import dump_runtime_manifest, unbuilt_manifest
from hermes_cpa.settings import CpaSettings
from runtime_fixtures import BINARY, make_package, pin_runtime, write_archive


class Owner:
    generation = 1
    mode = 'managed'
    policy_locked = False
    running = True
    owned = True
    stop_result = True

    def __init__(self):
        self.calls = []
        self.entered = False
        self.on_enter = lambda: None

    @property
    @contextmanager
    def mutation_gate(self):
        self.entered = True
        self.on_enter()
        try:
            yield
        finally:
            self.entered = False

    def assert_owned(self):
        assert self.entered
        if not self.owned:
            raise RuntimeError('secret-canary ownership failure')

    def stop_owned_and_reap(self):
        assert self.entered
        self.calls.append('stop')
        if isinstance(self.stop_result, Exception):
            raise self.stop_result
        if self.stop_result:
            self.running = False
        return self.stop_result

    def start_owned_and_poll_readiness(self):
        self.calls.append('start')
        raise AssertionError('No restart authorized by gate slice')


def make_archive(path, members=None, binary=BINARY, root=None):
    """Write the generated archive and, with ROOT, pin it in that package's metadata."""
    write_archive(path, binary, members or [])
    if root is not None:
        pin_runtime(root, path, binary)
    return binary


@pytest.fixture
def case(tmp_path):
    settings = CpaSettings(tmp_path / 'home')
    settings.instances_dir.mkdir(parents=True, mode=0o700)
    settings.config_path.write_bytes(b'config-version: 8\nunknown: retained\n')
    settings.config_path.chmod(0o600)
    archive = tmp_path / 'generated.tar.gz'
    write_archive(archive, BINARY)
    root = tmp_path / 'package'
    manifest = make_package(root, archive, BINARY)
    installer = CpaInstaller(settings, root)
    revision = ConfigStore(settings.config_path).compute_digest()
    return SimpleNamespace(settings=settings, archive=archive, installer=installer,
        owner=Owner(), manifest=manifest, root=root, tmp=tmp_path,
        args=dict(expected_generation=1, expected_revision=revision, native_consent=True))


@pytest.mark.parametrize('operation', ['upgrade', 'remove'])
@pytest.mark.parametrize('field,value,code', [
    ('mode', 'external', 'READ_ONLY'), ('policy_locked', True, 'POLICY_LOCKED'),
    ('generation', 2, 'STALE_GENERATION'), ('owned', False, 'OWNERSHIP_LOST')])
def test_authority_refusals(case, operation, field, value, code):
    setattr(case.owner, field, value)
    result = invoke(case, operation)
    assert result['code'] == code
    assert not result['ok'] and result['rollback'] == 'not_attempted'
    assert not case.owner.calls
    assert not case.settings.bin_dir.exists()
    assert 'secret-canary' not in str(result)


def invoke(case, operation):
    args = (case.archive, case.owner) if operation == 'upgrade' else (case.owner,)
    return getattr(case.installer, operation)(*args, **case.args)


@pytest.mark.parametrize('operation', ['upgrade', 'remove'])
@pytest.mark.parametrize('key,value,code', [
    ('expected_generation', True, 'STALE_GENERATION'),
    ('expected_generation', 0, 'STALE_GENERATION'),
    ('expected_revision', '', 'STALE_REVISION'),
    ('expected_revision', 'f' * 64, 'STALE_REVISION'),
    ('expected_revision', True, 'STALE_REVISION'),
    ('native_consent', False, 'CONSENT_REQUIRED'),
    ('native_consent', 1, 'CONSENT_REQUIRED')])
def test_request_refusals(case, operation, key, value, code):
    case.args[key] = value
    assert invoke(case, operation)['code'] == code
    assert not case.owner.calls


@pytest.mark.parametrize('operation', ['upgrade', 'remove'])
def test_recheck_after_queue(case, operation):
    case.owner.on_enter = lambda: setattr(case.owner, 'policy_locked', True)
    assert invoke(case, operation)['code'] == 'POLICY_LOCKED'
    assert not case.owner.calls


def test_upgrade_requires_unavailable_recovery_before_writes(case):
    before = case.settings.config_path.read_bytes()
    result = invoke(case, 'upgrade')
    assert result['code'] == 'RECOVERY_REQUIRED'
    assert result['revision'] == case.args['expected_revision']
    assert not case.owner.calls and not case.settings.bin_dir.exists()
    assert case.settings.config_path.read_bytes() == before


@pytest.mark.parametrize('damage', ['console', 'notices', 'pair', 'hash', 'manifest', 'runtime',
                                    'unpinned', 'stock_pair', 'pair_digest'])
def test_target_rejected_before_stop_or_stage(case, damage):
    if damage == 'console':
        (case.root / 'assets/cpamc.html').write_bytes(b'changed')
    elif damage == 'notices':
        (case.root / 'LICENSE').unlink()
    elif damage == 'pair':
        case.manifest['supported_pairs'][0]['cpa_version'] = '8.0.22'
        (case.root / 'compatibility.json').write_text(json.dumps(case.manifest))
    elif damage == 'hash':
        case.archive.write_bytes(b'bad')
    elif damage == 'runtime':
        (case.root / 'cpa-runtime.json').write_bytes(b'{}')
    elif damage == 'unpinned':
        (case.root / 'cpa-runtime.json').write_bytes(dump_runtime_manifest(unbuilt_manifest()))
    elif damage == 'stock_pair':
        del case.manifest['supported_pairs'][0]['integration']
        (case.root / 'compatibility.json').write_text(json.dumps(case.manifest))
    elif damage == 'pair_digest':
        case.manifest['supported_pairs'][0]['archive_sha256'] = 'f' * 64
        (case.root / 'compatibility.json').write_text(json.dumps(case.manifest))
    else:
        (case.root / 'compatibility.json').write_bytes(b'[]')
    assert invoke(case, 'upgrade')['code'] == 'INVALID_TARGET'
    with pytest.raises((ValueError, OSError, RuntimeError)):
        case.installer.install_from_archive(case.archive)
    assert not case.owner.calls and not case.settings.bin_dir.exists()


@pytest.mark.parametrize('stop_result', [False, RuntimeError('secret-canary')])
def test_removal_stop_failure_is_uncertain(case, stop_result):
    case.owner.stop_result = stop_result
    result = invoke(case, 'remove')
    assert result['code'] == 'STOP_FAILED'
    assert result['running_state'] == 'unknown' and result['data_retained']
    assert result['package_removed'] is False
    assert 'secret-canary' not in str(result)


def test_removal_is_only_preparation_and_retains_all_bytes(case):
    paths = [case.tmp / 'provider-settings', case.settings.instances_dir / 'auth-fixture',
             case.settings.instances_dir / 'backup-fixture', case.root / 'LICENSE']
    for path in paths[:3]:
        path.write_bytes(b'generated sentinel')
    before = {p: p.read_bytes() for p in paths + [case.settings.config_path]}
    result = invoke(case, 'remove')
    assert result['ok'] and result['code'] == 'OK'
    assert result['data_retained'] and result['removal_prepared']
    assert result['package_removed'] is False and result['supervisor_terminated'] is None
    assert case.owner.calls == ['stop']
    assert all(p.read_bytes() == raw for p, raw in before.items())


@pytest.mark.parametrize('names', [('cli-proxy-api/child',), ('dir/file', 'dir'), ('a', './a')])
def test_archive_parent_file_and_normalized_duplicate_rejected(case, names):
    members = [tarfile.TarInfo(name) for name in names]
    make_archive(case.archive, members, root=case.root)
    with pytest.raises(ValueError, match='unsafe_archive_member'):
        case.installer.install_from_archive(case.archive)
    assert not case.settings.bin_dir.exists()


def test_private_immutable_initial_stage(case):
    assert case.installer.install_from_archive(case.archive)
    assert case.installer.verify_pair()
    binary = case.settings.binary_path
    assert binary.stat().st_mode & 0o777 == 0o700
    assert binary.parent.stat().st_mode & 0o777 == 0o700
    before = binary.read_bytes()
    with pytest.raises(ValueError, match='upgrade_required'):
        case.installer.install_from_archive(case.archive)
    assert binary.read_bytes() == before


def test_symlink_binary_parent_refused(case):
    outside = case.tmp / 'outside'
    outside.mkdir()
    case.settings.bin_dir.parent.mkdir(parents=True)
    case.settings.bin_dir.symlink_to(outside, target_is_directory=True)
    with pytest.raises((ValueError, RuntimeError)):
        case.installer.install_from_archive(case.archive)
    assert not list(outside.iterdir())
